void velocityVerletStep2(vec3& vel, const vec3& force, double mass, double dt) {
    vel += 0.5 * (force / mass) * dt;
}

void velocityVerletStep2(vec3& vel, const vec3& force, double mass, double dt) {
    vec3 acceleration = force / mass;
    vel += 0.5 * acceleration * dt;
}

void velocityVerletStep2(vec3& vel, const vec3& force, double mass, double dt) {
    vel += 0.5 * force * dt / mass;
}

